UPDATE public.parts_new SET availability = 'on_order' WHERE COALESCE(price_with_vat,0) = 0 AND COALESCE(catalog_source,'') IN ('mopar','mopar_oem','7zap','epc-ai','ai-epc','epc-link','csv','crossref','autokelly','makro','') AND COALESCE(availability,'') != 'on_order';
UPDATE public.auto_pipeline_queue SET status = 'pending', attempts = 0, error_message = NULL WHERE status = 'processing' AND (now() - created_at) BETWEEN interval '30 minutes' AND interval '365 days';
INSERT INTO public.auto_pipeline_queue (job_type, part_id, oem_number, status) SELECT 'fetch_price', p.id, p.oem_number, 'pending' FROM public.parts_new p WHERE COALESCE(p.price_with_vat,0) = 0 AND COALESCE(p.catalog_source,'') IN ('mopar','mopar_oem','7zap','epc-link','csv') AND p.oem_number ~ '^K?[0-9]{8}[A-Z]{0,3}$' AND NOT EXISTS (SELECT 1 FROM public.auto_pipeline_queue q WHERE q.part_id = p.id AND q.job_type = 'fetch_price' AND q.status IN ('pending','processing'));
DO $mig$ BEGIN PERFORM cron.unschedule('auto-pipeline-worker'); EXCEPTION WHEN OTHERS THEN NULL; END $mig$;
SELECT cron.schedule('auto-pipeline-worker', '*/2 * * * *', $cron$ SELECT net.http_post(url := 'https://nzmeiluvpmchipyssdms.supabase.co/functions/v1/auto-pipeline-worker', headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im56bWVpbHV2cG1jaGlweXNzZG1zIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzI1ODM5MDksImV4cCI6MjA4ODE1OTkwOX0.1jnb06nPP9H91B7UYZK593JyeoMNyQCysp3VKUmcPa4'), body := '{}'::jsonb); $cron$);